42	{
43	    session_stats_t initial_stats;
44	    study_state_t initial_study;
45	
46	    /* 真实 perception 接口 (PERCEPTION_MOCK 时内部走 mock, 真实 MiMo 配置后自动切换) */
47	    printf("[perception] init\n");
48	    perception_init(NULL, NULL);
49	
50	    printf("[behavior]  init mode=STRICT\n");
51	    behavior_init(MODE_STRICT);
52	
53	    /* 张沐泽硬件驱动初始化 (stub 模式为 no-op, 真实模式配置 GPIO/I2S/摄像头) */
54	    button_init();
55	    audio_init();
56	    camera_init();
57	
58	    if (lcd_init() == FOCUS_OK)
59	    {
60	        memset(&initial_stats, 0, sizeof(initial_stats));
61	        memset(&initial_study, 0, sizeof(initial_study));
62	        initial_study.status = FOCUSED;
63	        if (lcd_show_status(DEVICE_IDLE, &initial_stats,
64	                            &initial_study) == FOCUS_OK)
65	        {
66	            printf("[ui]        LCD UI initialized\n");
67	        }
68	        else
69	        {
70	            printf("[ui]        LCD UI unavailable\n");
71	        }
72	    }
73	    else
74	    {
75	        printf("[ui]        LCD backend unavailable\n");
76	    }
77	}
