88	/* `hello_app hwbutton`: 真实按键事件测试 (10s) */
89	static int hw_test_button(void)
90	{
91	    int i;
92	    button_init();  /* 子命令不走 init_modules, 需自行初始化 */
93	    printf("===== 硬件验证: 按键 (真实 GPIO) =====\n");
94	    printf("请按 BOOT 键: 短按(<1s)/长按(1-3s)/超长按(>3s), 10 秒...\n");
95	    for (i = 0; i < 100; i++)
96	    {
97	        button_event_t ev = button_get_event();
98	        if (ev != BTN_NONE)
99	        {
100	            printf("  按键事件: %d (%s)\n", (int)ev,
101	                   ev == BTN_START_SHORT ? "短按" :
102	                   ev == BTN_START_LONGPRESS ? "长按" :
103	                   ev == BTN_STOP ? "超长按" : "其他");
104	        }
105	        usleep(100 * 1000);
106	    }
107	    return 0;
108	}
