125	/* `hello_app hwcamera`: 摄像头采集 3 帧 */
126	static int hw_test_camera(void)
127	{
128	    uint8_t *buf;
129	    size_t size = 0;
130	    int i;
131	    int ret;
132	
133	    printf("===== 硬件验证: 摄像头 (OV2640) =====\n");
134	    ret = camera_init();
135	    if (ret != FOCUS_OK)
136	    {
137	        printf("  [FAIL] camera_init: %d\n", ret);
138	        return 1;
139	    }
140	
141	    buf = malloc(320 * 240 * 2);  /* RGB565 全尺寸 */
142	    if (buf == NULL)
143	    {
144	        printf("  [FAIL] 内存不足\n");
145	        camera_deinit();
146	        return 1;
147	    }
148	
149	    printf("  采集 3 帧 (驱动单帧模式, 首帧成功即验证链路)...\n");
150	    for (i = 0; i < 3; i++)
151	    {
152	        ret = camera_capture_frame(buf, &size);
153	        if (ret == FOCUS_OK)
154	        {
155	            printf("  frame %d: %u bytes\n", i, (unsigned)size);
156	        }
157	        else
158	        {
159	            printf("  frame %d: FAILED (%d) — 单帧模式后续帧失败为预期\n", i, ret);
160	        }
161	        usleep(500 * 1000);
162	    }
163	
164	    free(buf);
165	    camera_deinit();
166	
167	    if (size > 0)
168	    {
169	        printf("  [PASS] 摄像头链路正常 (采到 %u 字节帧)\n", (unsigned)size);
170	        return 0;
171	    }
172	
173	    printf("  [FAIL] 未采到有效帧\n");
174	    return 1;
175	}
