177	/* `hello_app hwwifi <ssid> <password>`: WiFi 连接 + HTTP POST 测试 */
178	static int hw_test_wifi(int argc, char *argv[])
179	{
180	    char resp[1024];
181	    int ret;
182	
183	    if (argc < 4)
184	    {
185	        printf("用法: hello_app hwwifi <ssid> <password>\n");
186	        return 1;
187	    }
188	
189	    printf("===== 硬件验证: WiFi =====\n");
190	    /* argv: [hello_app, hwwifi, ssid, password] → ssid=argv[2], pass=argv[3] */
191	    ret = wifi_connect(argv[2], argv[3]);
192	    printf("  wifi_connect=%d connected=%d rssi=%d dBm\n",
193	           ret, wifi_is_connected(), wifi_get_rssi());
194	
195	    /* DHCP 获取 IP + DNS (netlib_obtain_ipv4addr, 阻塞至完成) */
196	    printf("  获取 IP (DHCP)...\n");
197	    {
198	        int ipret = netlib_obtain_ipv4addr("wlan0");
199	        printf("  DHCP ret=%d\n", ipret);
200	    }
201	
202	    ret = wifi_http_post("http://httpbin.org/post",
203	                         "{\"test\":1}", resp, sizeof(resp));
204	    printf("  HTTP POST=%d\n", ret);
205	    if (ret == FOCUS_OK)
206	    {
207	        printf("  resp: %.200s\n", resp);
208	    }
209	
210	    return ret == FOCUS_OK ? 0 : 1;
211	}
