213	/* ==================== 主入口 ==================== */
214	
215	int main(int argc, char *argv[])
216	{
217	    if (argc > 1)
218	    {
219	        if (strcmp(argv[1], "hwbutton") == 0) return hw_test_button();
220	        if (strcmp(argv[1], "hwaudio") == 0)  return hw_test_audio();
221	        if (strcmp(argv[1], "hwcamera") == 0) return hw_test_camera();
222	        if (strcmp(argv[1], "hwwifi") == 0)   return hw_test_wifi(argc, argv);
223	        printf("未知命令: %s\n", argv[1]);
224	        printf("用法: hello_app [hwbutton|hwaudio|hwcamera|hwwifi <ssid> <pass>]\n");
225	        return 1;
226	    }
227	
228	    printf("\n");
229	    printf("==================================================\n");
230	    printf("  FOCUS AIoT v0.3 (真实硬件驱动)\n");
231	    printf("  板卡: ESP32-S3-EYE / openvela\n");
232	    printf("==================================================\n");
233	    printf("  模块状态:\n");
234	    printf("    state_machine  - 真实 FSM (core/state_machine.c)\n");
235	    printf("    ui             - 郭黄亦昕 (已集成)\n");
236	    printf("    behavior       - 赵思涵时序引擎\n");
237	    printf("    button/audio/camera/wifi - 张沐泽真实驱动\n");
238	    printf("    perception     - 周礼航感知 (mock 或真实 MiMo)\n");
239	    printf("  子命令: hello_app hwbutton|hwaudio|hwcamera|hwwifi <ssid> <pass>\n");
240	    printf("==================================================\n\n");
241	
242	    /* ---- 模块初始化 ---- */
243	    init_modules();
244	    state_machine_init();
245	
246	    /* ---- 摄像头/感知帧缓冲 (PSRAM heap, 主循环复用) ---- */
247	    {
248	        uint8_t *frame = malloc(320 * 240 * 2);   /* RGB565 帧 */
249	        /* JPEG 输出: 必须 ≥ 3×帧大小。TinyJPEG quality=2 细节多时
250	         * 输出可超 width*height (实测噪声帧约 2.8×), 太小会截断丢
251	         * EOI 标记, MiMo 解码 400。 */
252	        uint8_t *jpeg_buf = malloc(320 * 240 * 3);
253	        observation_t obs;
254	        int frame_tick = 0;
255	
256	        memset(&obs, 0, sizeof(obs));
257	        if (frame == NULL || jpeg_buf == NULL)
258	        {
259	            printf("[core] 帧缓冲分配失败, 感知暂停\n");
260	        }
261	
262	        printf("[core] 进入主循环: 状态机 @10Hz + 感知 @5s/帧...\n");
263	        printf("[core] 真实按键: 长按进模式选择, 短按开始, 超长按停止\n\n");
264	
265	        /* ---- 主循环: state_machine + 感知驱动 ---- */
266	        for (;;)
267	        {
268	            state_machine_tick();   /* 内部 behavior_analyze 消费感知历史 */
269	
270	            /* 每 50 tick (5s) 采一帧喂感知, 更新 history 供行为引擎 */
271	            if (++frame_tick >= 50)
272	            {
273	                frame_tick = 0;
274	#ifdef PERCEPTION_MOCK
275	                /* mock: 假帧驱动 (perception 内部走 mock_observation) */
276	                if (frame != NULL)
277	                {
278	                    memset(frame, 0, 64);
279	                    perception_process(frame, 64, &obs);
280	                }
281	#else
282	                /* 真实: 摄像头采集 RGB565 → 转 JPEG → MiMo 识图 */
283	                if (frame != NULL && jpeg_buf != NULL)
284	                {
285	                    static unsigned cap_seq = 0;
286	                    size_t fsize = 0;
287	                    size_t jpeg_size = 320 * 240 * 3;
288	                    int cret;
289	                    int pret;
290	
291	                    /* 每次采集都在串口打点, 便于真机核对采集/识图节奏 */
292	                    printf("[cam] #%u 尝试采集...\n", ++cap_seq);
293	                    cret = camera_capture_frame(frame, &fsize);
294	                    if (cret == FOCUS_OK && fsize > 0)
295	                    {
296	                        printf("[cam] #%u 采集OK %uB -> 转JPEG...\n",
297	                               cap_seq, (unsigned)fsize);
298	                        if (rgb565_to_jpeg(frame, 320, 240,
299	                                           jpeg_buf, &jpeg_size) == 0)
300	                        {
301	                            printf("[cam] #%u JPEG %uB -> 云端识图...\n",
302	                                   cap_seq, (unsigned)jpeg_size);
303	                            pret = perception_process(jpeg_buf, jpeg_size, &obs);
304	                            printf("[cam] #%u 识图返回=%d person=%d phone=%d "
305	                                   "pitch=%.1f motion=%.2f conf=%.2f\n",
306	                                   cap_seq, pret,
307	                                   (int)obs.person_present,
308	                                   (int)obs.phone_detected,
309	                                   obs.head_pitch,
310	                                   obs.hand_motion_score,
311	                                   obs.confidence);
312	                        }
313	                        else
314	                        {
315	                            printf("[cam] #%u JPEG 编码失败\n", cap_seq);
316	                        }
317	                    }
318	                    else
319	                    {
320	                        printf("[cam] #%u 采集失败 ret=%d errno=%d\n",
321	                               cap_seq, cret, errno);
322	                    }
323	                }
324	#endif
325	            }
326	
327	            usleep(100 * 1000);  /* 100ms = 10Hz */
328	        }
329	    }
330	
331	    return EXIT_SUCCESS;
332	}
