1	/****************************************************************************
2	 * FOCUS AIoT - 主控状态机与会话统计 (core/state_machine.c)
3	 *
4	 * 负责人: 万思源
5	 * 职责: 4 状态 FSM (IDLE → MODE_SELECT → MONITORING → REPORT)
6	 *       消费按键事件 + 行为分析结果，驱动计时/评分/提醒/报告。
7	 *
8	 * 依赖 (通过 api 头文件):
9	 *   - button_get_event()  张沐泽
10	 *   - behavior_analyze()  赵思涵  ★ 每个 tick 只调用一次 (有状态)
11	 *   - behavior_set_mode() 赵思涵
12	 *   - lcd_show_*()        郭黄亦昕
13	 *   - audio_play_*()      张沐泽
14	 *
15	 * 设计要点:
16	 *   - state_machine_tick() 由主循环以 ~10Hz 调用。
17	 *   - 有效学习时长: 仅当 behavior 返回 FOCUSED 时累计 elapsed。
18	 *   - 评分只累加 behavior 输出的 focus_score_delta, 不自己算分。
19	 *   - 暂停期间不加有效时长、不触发提醒。
20	 *   - behavior_analyze() 每 tick 仅调用一次, 结果缓存供 UI 复用。
21	 ****************************************************************************/
22	
23	#include <nuttx/config.h>
24	
25	#include <stdio.h>
26	#include <string.h>
27	#include <time.h>
28	
29	#include "../api/error.h"
30	#include "../api/button.h"
31	#include "../api/behavior.h"
32	#include "../api/state_machine.h"
33	#include "../api/session.h"
34	#include "../api/lcd.h"
35	#include "../api/audio.h"
36	
37	/* ---- 常量 ---- */
38	#define UI_REFRESH_INTERVAL_MS 1000U  /* UI 刷新间隔 */
39	#define SCORE_INITIAL         100
40	#define SCORE_MIN             0
41	#define SCORE_MAX             100
42	
43	/* ---- 内部状态 ---- */
44	static device_status_t g_state      = DEVICE_IDLE;
45	static int             g_mode       = MODE_STRICT;
46	static bool            g_paused     = false;
47	
48	static session_stats_t g_stats;
49	static uint8_t         g_distraction_by_type[DIST_TYPE_COUNT];
50	static int             g_score = SCORE_INITIAL;
51	static session_report_t g_report;
52	
53	/* 最新一次 behavior 分析结果 (缓存供 UI 复用) */
54	static study_state_t   g_latest_study;
55	
56	/* 时间基准 (单调时钟, 毫秒) */
57	static uint64_t g_last_tick_ms   = 0;   /* 上次 tick 时间 */
58	static uint64_t g_last_ui_ms     = 0;   /* 上次 UI 刷新时间 */
59	static uint64_t g_accumulated_ms = 0;   /* 未折算成秒的累计毫秒 */
60	
61	/* ---- 前向声明 ---- */
62	static uint64_t monotonic_ms(void);
63	static void     transition_to(device_status_t next);
64	static void     start_session(void);
65	static void     end_session(void);
66	static void     reset_session(void);
67	static void     toggle_mode(void);
68	static void     process_study_state(const study_state_t *ss);
69	static void     trigger_remind(const study_state_t *ss);
70	static void     trigger_encourage(const study_state_t *ss);
71	static void     refresh_ui(void);
72	
73	/* ==================== 单调时钟 ==================== */
74	
75	static uint64_t monotonic_ms(void)
76	{
77	  struct timespec ts;
78	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
79	    {
80	      return 0;
81	    }
82	  return (uint64_t)ts.tv_sec * 1000U + (uint64_t)ts.tv_nsec / 1000000U;
83	}
84	
85	/* ==================== 状态转移 ==================== */
86	
87	static void transition_to(device_status_t next)
88	{
89	  static const char *const names[] =
90	    { "IDLE", "MODE_SELECT", "MONITORING", "REPORT" };
91	  const char *from = (g_state >= DEVICE_IDLE && g_state <= DEVICE_REPORT)
92	                     ? names[g_state] : "?";
93	  const char *to   = (next   >= DEVICE_IDLE && next   <= DEVICE_REPORT)
94	                     ? names[next]   : "?";
95	
96	  g_state = next;
97	  printf("[state_machine] %s -> %s\n", from, to);
98	}
99	
100	/* ==================== 会话生命周期 ==================== */
101	
102	static void start_session(void)
103	{
104	  uint64_t now = monotonic_ms();
105	  g_last_tick_ms   = now;
106	  g_last_ui_ms     = 0;  /* 立即刷新一次 */
107	  g_accumulated_ms = 0;
108	
109	  memset(&g_stats, 0, sizeof(g_stats));
110	  memset(g_distraction_by_type, 0, sizeof(g_distraction_by_type));
111	
112	  g_stats.session_start = (uint32_t)(now / 1000U);
113	  g_stats.current_mode  = (uint8_t)g_mode;
114	  g_stats.focus_score   = SCORE_INITIAL;
115	  g_score               = SCORE_INITIAL;
116	  g_paused              = false;
117	
118	  printf("[state_machine] 会话开始 mode=%s\n",
119	         g_mode == MODE_STRICT ? "STRICT" : "GENTLE");
120	}
121	
122	static void end_session(void)
123	{
124	  g_stats.focus_score = (uint8_t)g_score;
125	
126	  memset(&g_report, 0, sizeof(g_report));
127	  g_report.stats = g_stats;
128	  memcpy(g_report.distraction_by_type, g_distraction_by_type,
129	         sizeof(g_distraction_by_type));
130	  /* advice 由 UI 层调 mimo_get_advice() 填充 */
131	
132	  printf("[state_machine] 会话结束: 总%us 有效%us 分心%u次 评分%u\n",
133	         g_stats.total_duration_sec,
134	         g_stats.effective_duration_sec,
135	         g_stats.distraction_count,
136	         g_stats.focus_score);
137	}
138	
139	static void reset_session(void)
140	{
141	  g_paused = false;
142	  g_score  = SCORE_INITIAL;
143	  memset(&g_stats, 0, sizeof(g_stats));
144	  memset(g_distraction_by_type, 0, sizeof(g_distraction_by_type));
145	  memset(&g_report, 0, sizeof(g_report));
146	  printf("[state_machine] 会话已复位\n");
147	}
148	
149	static void toggle_mode(void)
150	{
151	  g_mode = (g_mode == MODE_STRICT) ? MODE_GENTLE : MODE_STRICT;
152	  behavior_set_mode(g_mode);
153	  g_stats.current_mode = (uint8_t)g_mode;
154	  printf("[state_machine] 切换模式 -> %s\n",
155	         g_mode == MODE_STRICT ? "STRICT" : "GENTLE");
156	}
157	
158	/* ==================== 评分 ==================== */
159	
160	static void add_score_delta(int delta)
161	{
162	  g_score += delta;
163	  if (g_score < SCORE_MIN) g_score = SCORE_MIN;
164	  if (g_score > SCORE_MAX) g_score = SCORE_MAX;
165	  g_stats.focus_score = (uint8_t)g_score;
166	}
167	
168	/* ==================== 行为结果消费 ==================== */
169	
170	static void process_study_state(const study_state_t *ss)
171	{
172	  /* 评分增量 */
173	  if (ss->focus_score_delta != 0)
174	    {
175	      add_score_delta(ss->focus_score_delta);
176	    }
177	
178	  /* 分心计数与类型 + 提醒 */
179	  if (ss->action == REMIND)
180	    {
181	      g_stats.distraction_count++;
182	      switch (ss->status)
183	        {
184	          case PLAYING_PHONE:
185	            g_distraction_by_type[DIST_PLAYING_PHONE]++;
186	            break;
187	          case GLANCING_PHONE:
188	            g_distraction_by_type[DIST_GLANCING_PHONE]++;
189	            break;
190	          case AWAY:
191	            g_distraction_by_type[DIST_AWAY]++;
192	            break;
193	          case DROWSY:
194	            g_distraction_by_type[DIST_DROWSY]++;
195	            break;
196	          default:
197	            break;
198	        }
199	      trigger_remind(ss);
200	    }
201	  else if (ss->action == ENCOURAGE)
202	    {
203	      trigger_encourage(ss);
204	    }
205	}
206	
207	/* ==================== 提醒/鼓励触发 ==================== */
208	
209	static void trigger_remind(const study_state_t *ss)
