315	            printf("[state_machine] %s\n", g_paused ? "暂停" : "恢复");
316	          }
317	        else if (btn == BTN_PAUSE_LONGPRESS || btn == BTN_STOP)
318	          {
319	            end_session();
320	            transition_to(DEVICE_REPORT);
321	          }
322	        break;
323	
324	      case DEVICE_REPORT:
