354	            }
355	        }
356	
357	      process_study_state(&g_latest_study);
358	    }
359	
360	  /* ---- 4. UI 刷新 (节流到 1Hz) ---- */
361	  if (g_last_ui_ms == 0 || (now - g_last_ui_ms) >= UI_REFRESH_INTERVAL_MS)
362	    {
363	      g_last_ui_ms = now;
364	      refresh_ui();
365	    }
