    @staticmethod
    def _extract_jpeg_b64(body):
        """从 OpenAI 兼容请求体提取 data:image/jpeg;base64,<b64>。
        设备侧 perception.c 用 snprintf 拼 JSON, b64 只含 A-Za-z0-9+/=,
        所以取到下一个引号即可 (无需 JSON 库)。"""
        marker = b"data:image/jpeg;base64,"
        idx = body.find(marker)
        if idx < 0:
            return None
        start = idx + len(marker)
        end = body.find(b'"', start)
        if end < 0:
            end = len(body)
        return body[start:end]
```

```python
    def _save_preview_frame(self, body):
        try:
            b64 = self._extract_jpeg_b64(body)
            if b64 is None:
                return
            data = base64.b64decode(b64)
            if len(data) < 4:  # 空/损坏帧丢弃
                return
            tmp = PREVIEW_JPEG_PATH + ".tmp"
            with open(tmp, "wb") as f:
                f.write(data)
            os.replace(tmp, PREVIEW_JPEG_PATH)  # 原子替换, 网页读不到半张图
            print("[relay] preview saved %d bytes" % len(data))
        except Exception as e:
